/// <summary>
/// PricingAttribute of table <c>InventItemLocation</c> field PickingLocationMaxQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventItemLocationPickingLocationMaxQty extends UPSPricingAttributeInventItemLocation implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventItemLocation, PickingLocationMaxQty);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::Real);
    InventItemLocation inventItemLocation;

    while select inventItemLocation
        group by PickingLocationMaxQty
    {
        if (! ret.in(inventItemLocation.PickingLocationMaxQty))
        {
            ret.add(inventItemLocation.PickingLocationMaxQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventItemLocation, PickingLocationMaxQty));
    qbr.value(queryValue(_value));
}
